@page "/apply"
@using sv_293f9f8e28524b388ef43f80547e4de6.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation errors *@
    @if (errors.Count > 0)
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    @if (currentStep == 0)
    {
        @* Step 1: Personal Info *@
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <textarea id="address" @bind="address" placeholder="Enter your address"></textarea>
            </div>
            <div class="form-actions">
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    }
    else if (currentStep == 1)
    {
        @* Step 2: Work History *@
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (workEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <input type="checkbox" id="current-@index" @bind="workEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="workEntries[index].Description" placeholder="Describe your responsibilities"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    }
    else if (currentStep == 2)
    {
        @* Step 3: References *@
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (references.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="references[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="references[index].Relationship" placeholder="e.g. Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="references[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone</label>
                        <input type="tel" @bind="references[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (references.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    }
    else if (currentStep == 3)
    {
        @* Step 4: Cover Letter *@
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" class="cover-letter-input" @bind="coverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit..." maxlength="2000"></textarea>
                <div class="character-count">@(coverLetter?.Length ?? 0) / 2000 characters</div>
            </div>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    }
    else if (currentStep == 4)
    {
        @* Step 5: Review & Submit *@
        <div class="step-content">
            @if (submitted)
            {
                <div class="submission-confirmation">
                    <div class="success-icon">&#10003;</div>
                    <h2>Application Submitted!</h2>
                    <p>Your application has been received successfully.</p>
                    <p class="application-id">Application ID: <strong>@applicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => NavigateToStep(0)">Edit</button>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => NavigateToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                            <br />
                            <span class="review-dates">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="review-description">@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => NavigateToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in references)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)
                            <br />
                            @reference.Email
                            @if (!string.IsNullOrWhiteSpace(reference.Phone))
                            {
                                <span> &middot; @reference.Phone</span>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => NavigateToStep(3)">Edit</button>
                    </div>
                    <p class="review-cover-letter">@coverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            }
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private int highestCompletedStep = -1;
    private List<string> errors = new();

    // Step 1: Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = "";

    // Step 5: Submit
    private bool isSubmitting = false;
    private bool submitted = false;
    private int applicationId = 0;

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step <= highestCompletedStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            currentStep = step;
            errors.Clear();
        }
    }

    private async Task NextStep()
    {
        errors.Clear();

        if (!await ValidateCurrentStep())
            return;

        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;

        currentStep++;
    }

    private void PreviousStep()
    {
        errors.Clear();
        if (currentStep > 0)
            currentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(fullName))
                    errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(email))
                    errors.Add("Email is required.");
                else
                {
                    var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
                    if (!isValidEmail)
                        errors.Add("Please enter a valid email address.");
                }
                if (string.IsNullOrWhiteSpace(phone))
                    errors.Add("Phone number is required.");
                if (string.IsNullOrWhiteSpace(address))
                    errors.Add("Address is required.");
                break;

            case 1:
                for (int i = 0; i < workEntries.Count; i++)
                {
                    var entry = workEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company))
                        errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title))
                        errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default)
                        errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;

            case 2:
                for (int i = 0; i < references.Count; i++)
                {
                    var r = references[i];
                    if (string.IsNullOrWhiteSpace(r.Name))
                        errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                        errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email))
                        errors.Add($"Reference {i + 1}: Email is required.");
                }
                break;

            case 3:
                // Cover letter is optional but has max length
                if (coverLetter?.Length > 2000)
                    errors.Add("Cover letter must be 2000 characters or fewer.");
                break;
        }

        return errors.Count == 0;
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;

        var personal = new PersonalInfo(fullName, email, phone, address);
        var work = new WorkHistory(workEntries.Select(e => new WorkEntry(
            e.Company,
            e.Title,
            e.StartDate,
            e.IsCurrent ? null : e.EndDate,
            e.Description ?? ""
        )).ToList());
        var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone ?? "")).ToList();
        var application = new JobApplication(personal, work, refs, coverLetter ?? "");

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        submitted = true;
        isSubmitting = false;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

