    transition: all 0.3s ease;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: #fff;
}

.step.dimmed .step-circle {
    border-color: #ddd;
    background: #f5f5f5;
    color: #bbb;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step.dimmed .step-label {
    color: #bbb;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
    transition: background 0.3s ease;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Validation Errors */
.validation-errors {
    background: #fff0f0;
    border: 1px solid #ffcdd2;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1.5rem;
